import{_ as r}from"./chunks/teaching-resources.JA42Qhq4.js";import{_ as a}from"./chunks/teaching-control.BkTtefWh.js";import{_ as o,o as s,c as l,a2 as n}from"./chunks/framework.BWuWLRhz.js";const i="/userguide/teaching-whiteboard.png",e="/userguide/teaching-replay.png",g="/userguide/teaching-physics.png",d="/userguide/teaching-chem.png",h="/userguide/teaching-plugins.png",k=JSON.parse('{"title":"教学模式","description":"AgoraIn 教学模式 —— 资源中心、白板批注与回放、物理电路实验、化学实验、集控平台与插件，一页讲清怎么用","frontmatter":{"title":"教学模式","description":"AgoraIn 教学模式 —— 资源中心、白板批注与回放、物理电路实验、化学实验、集控平台与插件，一页讲清怎么用"},"headers":[],"relativePath":"teaching.md","filePath":"teaching.md","lastUpdated":1792319862000}'),c={name:"teaching.md"};function p(u,t,m,_,f,b){return s(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="教学模式-希沃式授课台" tabindex="-1">教学模式（希沃式授课台） <a class="header-anchor" href="#教学模式-希沃式授课台" aria-label="Permalink to &quot;教学模式（希沃式授课台）&quot;">​</a></h1><p>教学模式的定位：<strong>把一节课要用的东西都收在一个页面里</strong> —— 课件、批注、实验演示、教室集控。 老师打开一个网页就能上课，不需要在多个软件之间切换。</p><h2 id="进入方式" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式" aria-label="Permalink to &quot;进入方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>管理面板入口</td><td>登录管理面板 → 左侧「教学模式」，自动携带登录态打开</td></tr><tr><td>登录页直达</td><td>登录页点「<strong>登录并进入教学模式</strong>」，登录成功后直接进入教学模式</td></tr><tr><td>直接地址</td><td><code>https://agorain.615mc.cn/teaching.html?token=&lt;登录令牌&gt;</code>（桌面端 / 移动端内嵌页面同样使用该地址）</td></tr></tbody></table><p>页面顶部有 6 个标签页：<strong>资源中心 · 白板授课 · 物理实验 · 化学实验 · 集控平台 · 插件</strong>； 右上角可<strong>选择班级</strong>，选中后白板、翻页与实验操作会<strong>实时同步</strong>给该班级的接收端（学生端 / 教室大屏）。</p><h2 id="一、资源中心" tabindex="-1">一、资源中心 <a class="header-anchor" href="#一、资源中心" aria-label="Permalink to &quot;一、资源中心&quot;">​</a></h2><p><img src="'+r+'" alt="资源中心"></p><p>上传一次，随时开讲：</p><ol><li>点「<strong>上传资源</strong>」，选择 PDF / Word / Excel / PPT / 图片（单个 ≤ 200MB）；</li><li>资源以卡片列出：类型、大小、页数、上传人、时间；</li><li>卡片操作：<strong>打开授课</strong>（进入白板授课并加载该文件）、<strong>下载</strong>、<strong>改名</strong>、<strong>删除</strong>（连同批注一并删除）；</li><li>顶部可按类型筛选（全部 / PDF / Word / Excel / PPT / 图片）。</li></ol><blockquote><p>PDF 与图片<strong>在线渲染</strong>（PDF 用 pdf.js，中文正常显示）；Word / Excel / PPT 目前不在线预览， 打开后是白板页，可下载原件本地打开 —— 批注、回放、实时同步不受影响。</p></blockquote><h2 id="二、白板授课-批注-回放" tabindex="-1">二、白板授课（批注 + 回放） <a class="header-anchor" href="#二、白板授课-批注-回放" aria-label="Permalink to &quot;二、白板授课（批注 + 回放）&quot;">​</a></h2><p><img src="'+i+'" alt="白板批注"></p><p>左侧工具栏：<strong>画笔 / 擦除 / 直线 / 矩形 / 椭圆 / 文字</strong>，5 种颜色，点「粗细」循环切换线宽。 顶部工具条：<strong>上一页 / 下一页 / ＋加页 / 撤销 / 清空本页 / 回放批注 / 全屏 / 下载原件 / 返回资源库</strong>。</p><p>使用要点：</p><ul><li><strong>批注自动保存</strong>：每一笔画完即写入服务端（按「资源 + 页」保存），换电脑打开同一资源，批注还在；</li><li><strong>回放批注</strong>：像希沃一样把本页批注<strong>按书写顺序动画重演</strong>，适合讲评与复盘；点「■ 停止」可中断；</li><li><strong>翻页/加页</strong>：PDF 页数自动识别；Office 文档与空白白板可用「＋加页」扩展页数；</li><li><strong>实时同步</strong>：选好班级后，笔迹、翻页、撤销、清空都会秒级推送到该班级的接收端；</li><li><strong>全屏</strong>：一键进入全屏授课，退出用 Esc。</li></ul><p><img src="'+e+'" alt="批注回放"></p><h2 id="三、物理实验-电路沙盘" tabindex="-1">三、物理实验（电路沙盘） <a class="header-anchor" href="#三、物理实验-电路沙盘" aria-label="Permalink to &quot;三、物理实验（电路沙盘）&quot;">​</a></h2><p><img src="'+g+'" alt="物理实验"></p><p>元件箱里的元件<strong>全部为本项目自绘矢量图</strong>，不依赖任何第三方实验素材：</p><table tabindex="0"><thead><tr><th>元件</th><th>说明</th></tr></thead><tbody><tr><td>电池（3V）</td><td>含内阻，可多节串联</td></tr><tr><td>开关</td><td>点一下合/断</td></tr><tr><td>小灯泡</td><td>按功率发光；功率超限会<strong>烧毁</strong></td></tr><tr><td>定值电阻</td><td>默认 10Ω</td></tr><tr><td>滑动变阻器</td><td>选中后用顶部滑块调阻值（0–20Ω）</td></tr><tr><td>电流表 / 电压表</td><td>实时读数</td></tr></tbody></table><p>操作流程：</p><ol><li>点左侧元件按钮放到实验台 → <strong>拖动</strong>摆位置（自动吸附网格）；</li><li>切到「<strong>连线</strong>」模式，点两个接线柱生成导线；右键导线可删除；</li><li>「<strong>选择/移动</strong>」模式下点开关合闸、双击元件或按 <code>R</code> 旋转 90°、选中后「删除选中」移除；</li><li>电路自动仿真：状态栏显示是否导通与干路电流，右侧面板给出电表读数与灯泡功率；</li><li>预设电路一键装载：<strong>串联电路 / 并联电路 / 伏安法测电阻</strong>。</li></ol><h2 id="四、化学实验-仪器-药品-反应" tabindex="-1">四、化学实验（仪器 + 药品 + 反应） <a class="header-anchor" href="#四、化学实验-仪器-药品-反应" aria-label="Permalink to &quot;四、化学实验（仪器 + 药品 + 反应）&quot;">​</a></h2><p><img src="'+d+'" alt="化学实验"></p><ul><li><strong>仪器</strong>：试管、烧杯、锥形瓶、集气瓶（最多同时放 6 件）；</li><li><strong>药品架</strong>：稀盐酸、稀硫酸、大理石、锌粒、过氧化氢、二氧化锰、高锰酸钾、氢氧化钠、硫酸铜溶液、铁钉、酚酞、紫色石蕊、澄清石灰水、水；</li><li><strong>操作</strong>：先点药品再双击仪器加入 → 选中仪器后「🔥 加热」（酒精灯动画）「✨ 点燃」「🫙 收集气体」「🔥 木条验满」；</li><li><strong>反应</strong>由规则表驱动，自动给出<strong>现象 + 化学方程式</strong>，例如： <ul><li>大理石 + 稀盐酸 → 大量气泡（CO₂）：<code>CaCO₃ + 2HCl = CaCl₂ + H₂O + CO₂↑</code></li><li>锌 + 稀硫酸 → 气泡（H₂）；H₂ 点燃 → 淡蓝色火焰</li><li>高锰酸钾加热 → O₂；二氧化锰催化过氧化氢 → O₂</li><li>澄清石灰水遇 CO₂ 变浑浊；铁钉浸硫酸铜 → 表面析出红色物质</li><li>酚酞遇碱变红、石蕊遇酸变红 / 遇碱变蓝</li></ul></li></ul><h2 id="五、集控平台-对齐-classisland-集控能力" tabindex="-1">五、集控平台（对齐 ClassIsland 集控能力） <a class="header-anchor" href="#五、集控平台-对齐-classisland-集控能力" aria-label="Permalink to &quot;五、集控平台（对齐 ClassIsland 集控能力）&quot;">​</a></h2><p><img src="'+a+'" alt="集控平台"></p><ul><li><strong>教室端设备</strong>：列出所有已登记的教室机（在线状态实时刷新）；目标可选「📢 广播」或指定某台；</li><li><strong>指令下发</strong>（13 类）：通知弹窗、语音播报、自定义消息、锁定屏幕、解锁屏幕、打开网页、启动应用、结束应用、 推送课表档案、刷新课表、休眠、重启、关机（电源类指令有二次确认）；</li><li><strong>指令历史</strong>：每条指令显示发送人、时间与<strong>执行回执</strong>（已执行 / 待执行 + 结果），可据此确认教室端是否真的执行了。</li></ul><h2 id="六、插件-可安装插件包" tabindex="-1">六、插件（可安装插件包） <a class="header-anchor" href="#六、插件-可安装插件包" aria-label="Permalink to &quot;六、插件（可安装插件包）&quot;">​</a></h2><p><img src="'+h+'" alt="插件管理"></p><ul><li>「安装插件包」上传 <code>.agp</code> 包 → 列表里<strong>启用 / 停用 / 重载 / 卸载</strong>；</li><li>已启用且自带界面的插件，会在下方「插件界面」下拉中列出，点开即用（内嵌 iframe）；</li><li>服务端集控插件 <strong>ClassIsland 集控平台（GPL-3.0）</strong> 就是从下载中心取包、在这里安装启用；</li><li>GPL 系插件安装时需勾选「已知悉开源合规」，且插件包必须声明源码地址 —— 详见<a href="/license.html">开源许可声明</a>。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：白板批注会丢吗？</strong> 不会。每笔画完即写入服务端（按资源 + 页存储）；换设备、换浏览器打开同一资源仍在。回放只影响显示，不改数据。</p><p><strong>Q：学生能看到我的批注吗？</strong> 只有在你<strong>选择了班级</strong>并保持连接时，白板与实验操作会实时推送到该班级的接收端。不选班级则只在本机显示。</p><p><strong>Q：Office 文件为什么不能直接批注在原文上？</strong> 在线渲染 Office 需要服务端转码，目前未启用；建议课前把课件导出为 PDF，就能获得完整批注体验。</p><p><strong>Q：实验数据是&quot;真算&quot;的吗？</strong> 物理电路使用**改进节点法（MNA）**实时求解，灯泡亮度、电表读数都来自计算；化学为规则表驱动，覆盖中学常见演示实验。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/custom-classisland.html">定制版 ClassIsland（集控客户端）</a></li><li><a href="/license.html">开源许可声明</a></li><li><a href="/manual.html">使用手册</a> · <a href="/features.html">功能特性</a></li></ul>',38)])])}const C=o(c,[["render",p]]);export{k as __pageData,C as default};
